        $method = 'SUBSCRIBE';
        if ($unwatch) {
            $method = 'UNSUBSCRIBE';
        }
        $recvWindow = $this->safe_string_2($this->options, 'recvWindow', 'X-Window', '5000');
        $payload = 'instruction=' . $instruction . '&' . 'timestamp=' . $ts . '&window=' . $recvWindow;
