    }

    public function handle_trades(Client $client, array $message) {
        //
        //     {
        //         data: {
        //             E: '1754601477746429',
        //             T: '1754601477744000',
        //             a: '5121860761',
        //             b: '5121861755',
        //             e: 'trade',
        //             m: false,
        //             p: '3870.25',
        //             q: '0.0008',
        //             s: 'ETH_USDC_PERP',
        //             t: 10782547
        //         },
        //         stream: 'trade.ETH_USDC_PERP'
        //     }
        //
        $data = $this->safe_dict($message, 'data', array());
        $marketId = $this->safe_string($data, 's');
        $market = $this->market($marketId);
        $symbol = $market['symbol'];
        if (!(is_array($this->trades) && array_key_exists($symbol ?? '', $this->trades))) {
            $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $stored = new ArrayCache($limit);
            $this->trades[$symbol] = $stored;
        }
        $cache = $this->trades[$symbol];
        $trade = $this->parse_ws_trade($data, $market);
        $cache->append($trade);
        $messageHash = 'trades:' . $symbol;
        $client->resolve($cache, $messageHash);
        $client->resolve($cache, 'trades');
    }

    public function parse_ws_trade(array $trade, ?array $market = null): array {
        //
        //     {
        //         E: '1754601477746429',
        //         T: '1754601477744000',
        //         a: '5121860761',
        //         b: '5121861755',
        //         e: 'trade',
        //         m: false,
        //         p: '3870.25',
        //         q: '0.0008',
        //         s: 'ETH_USDC_PERP',
        //         t: 10782547
        //     }
        //
        $microseconds = $this->safe_integer($trade, 'E', 0);
        $timestamp = $this->parse_to_int($microseconds / 1000);
        $id = $this->safe_string($trade, 't');
        $marketId = $this->safe_string($trade, 's');
        $marketResolved = $this->safe_market($marketId, $market);
        $isBuyerMaker = $this->safe_bool($trade, 'm');
        $side = null;
        $takerOrMaker = null;
        if ($isBuyerMaker !== null) {
            $takerOrMaker = 'taker';
            if ($isBuyerMaker) {
                $side = 'sell';
            } else {
                $side = 'buy';
            }
        }
        $price = $this->safe_string($trade, 'p');
        $amount = $this->safe_string($trade, 'q');
        $orderId = null;
        if ($side === 'buy') {
            $orderId = $this->safe_string($trade, 'b');
        } else {
            $orderId = $this->safe_string($trade, 'a');
        }
        return $this->safe_trade(array(
            'info' => $trade,
            'id' => $id,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $marketResolved['symbol'],
            'order' => $orderId,
            'type' => null,
            'side' => $side,
            'takerOrMaker' => $takerOrMaker,
            'price' => $price,
            'amount' => $amount,
            'cost' => null,
            'fee' => array(
                'currency' => null,
                'cost' => null,
            ),
        ), $marketResolved);
    }

    public function watch_order_book(string $symbol, ?int $limit = null, $params = array()): PromiseInterface {
