        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $this->handleStockParams('watchOrders', $query, $market);
        }
        $topic = 'account.orderUpdate';
        $messageHash = 'unsubscribe:orders';
        if ($market !== null) {
